candidates = [
    'drill', 'power drill', 'cordless drill',
    'hammer', 'claw hammer',
    'screwdriver', 'yellow screwdriver',
    'pliers', 'wrench', 'tape measure',
    'red toolbox', 'toolbox'
]

found_objects = {}
for name in candidates:
    r = primitives.call(
        name='submit_capx_action',
        action='get_object_pose',
        native_api=True,
        parameters={'object_name': name, 'return_bbox_extent': True}
    )
    if r.ok:
        res = r.output.get('native_api_result')
        if res and res[0] is not None:
            pos = res[0].get('values')
            print(f"FOUND {name}: pos = {pos}")
            found_objects[name] = pos
        else:
            print(f"not found: {name}")

items_to_test = [
    'drill', 'power drill', 'orange drill', 'cordless drill',
    'yellow screwdriver', 'screwdriver',
    'hammer', 'black rod', 'mallet',
    'red toolbox', 'toolbox'
]

detected = {}
for item in items_to_test:
    r = primitives.call(
        name='submit_capx_action',
        action='get_object_pose',
        native_api=True,
        parameters={'object_name': item, 'return_bbox_extent': True}
    )
    if r.ok:
        res = r.output.get('native_api_result')
        if res and res[0] is not None:
            pos = res[0].get('values')
            ext = res[2].get('values') if res[2] is not None else None
            print(f"DETECTED {item}: pos={pos}, ext={ext}")
            detected[item] = (pos, ext)
        else:
            print(f"none: {item}")

